{
    // EF Core 9 breaking change: Migrate() can no longer run inside a
    // user-managed transaction (it now manages its own). Remove the
    // surrounding transaction; the execution strategy retry is still valid.
    void ApplyMigrations(AppDbContext db)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            db.Database.Migrate();
        });
    }
}

