using Microsoft.EntityFrameworkCore;

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "https://localhost:8081",
            "C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==",
            "CatalogDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: The Cosmos provider now uses "$type"
        // as the default discriminator property name (aligning with modern
        // JSON polymorphism conventions). For existing documents that store
        // the discriminator in "Discriminator", you must explicitly configure it.
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");
            b.HasDiscriminator<string>("Discriminator")
                .HasValue<Product>("Product")
                .HasValue<DiscountedProduct>("DiscountedProduct");
        });
    }
}

class Product
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
}

class DiscountedProduct : Product
{
    public decimal Discount { get; set; }
}

using Microsoft.EntityFrameworkCore;

class CosmosQueryService
{
    // EF Core 9 breaking change: Synchronous I/O is no longer supported
    // by the Cosmos provider. All queries/saves must use async methods.
    // Before (broken in EF Core 9):
    //   var products = db.Products.ToList();
    //   db.SaveChanges();
    // After:
    async Task<List<Product>> GetProductsAsync(CosmosDbContext db)
    {
        return await db.Products.ToListAsync();
    }

    async Task SaveProductAsync(CosmosDbContext db, Product product)
    {
        db.Products.Add(product);
        await db.SaveChangesAsync();
    }
}

